import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/WikiName%E3%81%AE%E4%BD%9C%E3%82%8A%E6%96%B9.html","title":"WikiNameの作り方","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.88,"words":265},"filePathRelative":"WikiNameの作り方.md"}`),a={name:`WikiNameの作り方.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="wikinameの作り方" tabindex="-1"><a class="header-anchor" href="#wikinameの作り方"><span>WikiNameの作り方</span></a></h1><p>Wikiの使い方的な話。</p><h2 id="wikinameは今のページから作る" tabindex="-1"><a class="header-anchor" href="#wikinameは今のページから作る"><span>WikiNameは今のページから作る</span></a></h2><p>WikiNameは、なるべく今編集しているページから作るのがいい。 対極的なのがトップから階層化されたカテゴリの中に作る、というもの。 こういうのは良くない。</p><p>WikiNameはその関連が一番強いもの同士がいろいろなリンクで結ばれているのが良い。 トップからの階層は逆にリンクを最小で済ます分類方法となる。</p><p>また、トップからの階層を辿って作るのは、作成に手間が掛かる。 この作成の手間は、分類の手間とも言える。分類の手間を先に払うのは良くない。 以前ほげいか氏がそういうのは投機的な分類で、元手が回収されない事が多いので無駄が多いというような事を言っていたが、 そういう話だ。</p><p>WikiNameはなるべくたくさんある方が良い。階層的にWikiNameを管理するのはWikiNameを作るのをかったるくして、 だんだん作らない方向に圧力をかける。これは良くない。 だから今編集しているページからちょろっと作る方が望ましい。</p><p>分類は、必要と思ったら、必要な程度やる方が良い。必要になってからやるのが大切だ。</p><p>今編集しているページから作るというのは、ようするにそのWIkiNameが作りたくなった何かが今編集している内容に関連しているケースとなる。 こういうWikiNameによるリンクは理想的だ。 だからなるべく今のページから貼るのが良い。</p><p>後から探せなくなったりしないだろうか？と慣れないうちは不安になるだろうが、見つけられなくなる事はあまり無い。 そして「あれどこにあったかな？ここかな？」と思って探したところに無かったら、そこにリンクを足すのが良い。 この必要になった時にリンクを足す、を繰り返していく事で、 だんだんと構造が出来ていく構造の方が、階層的に整理するよりもずっと優れている。</p><p>カテゴリ的なものをつけたい時は、バックリンクをあてにしてカテゴリ名的なものへのリンクを貼る。 例えば<a href="./論文.html">論文</a>とか。この時、論文側から貼るのは良くない。 だいたい移動してから編集する、というのは良くない事が多い。 今いるところから行う方が良い。今編集しているページからリンクを貼る方が、論文などのページからリンクを貼るより良い。</p><h2 id="正式名よりも略称を" tabindex="-1"><a class="header-anchor" href="#正式名よりも略称を"><span>正式名よりも略称を</span></a></h2><p>論文の名前などでは、<a href="./ConvolutionalSequenceToSequenceLearning.html">ConvolutionalSequenceToSequenceLearning</a>よりは<a href="./ConvS2S.html">ConvS2S</a>の方が良い。 リンクを貼るのに略称の方が貼りやすく、なるべくリンクはたくさんある方が良いから。</p><p>一方、略称があまり一般的でなく、後から考えた時にそれが分からないようなケースもあるので、 正式名のWikiNameを作っておいて略称への参照を足しておくのも悪くはない。</p><p>ただ意外とgrepで探せるので正式名はいらないかもしれない。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};